export default {
  async fetch(request, env) {
    const incoming = new URL(request.url);
    const route = incoming.pathname.replace(/\/+$/, "") || "/";

    // Branded random-path endpoint generated by Script Protector:
    // https://arioscripts.cyou/<random-words>?s=<script-slug>
    // Browser navigation gets a branded page; Roblox HttpGet gets Lua source.
    const protectedSlug = incoming.searchParams.get("s") || "";
    const isRandomProtectedPath =
      route !== "/" &&
      !route.startsWith("/script/") &&
      !route.startsWith("/scripts/") &&
      !route.startsWith("/functions/") &&
      !route.includes(".") &&
      /^\/[a-z]+(?:-[a-z]+){3}$/.test(route);

    if (request.method === "GET" && protectedSlug && isRandomProtectedPath) {
      if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(protectedSlug) || protectedSlug.length > 80) {
        return new Response("Protected script not found.", {
          status: 404,
          headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }
        });
      }

      const accept = request.headers.get("accept") || "";
      if (accept.includes("text/html")) {
        const page = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#050505"><title>Protected Script · VOID DEVELOPMENT</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 0%,rgba(255,255,255,.12),transparent 48%),#050505;color:#fff;font:15px/1.7 system-ui,sans-serif;padding:24px}.card{width:min(620px,100%);text-align:center;padding:clamp(28px,6vw,52px);border:1px solid #ffffff20;border-radius:28px;background:#0c0c0cf2;box-shadow:0 28px 100px #0008}.brand{font-size:12px;letter-spacing:.3em;font-weight:800}.mark{width:64px;height:64px;display:grid;place-items:center;margin:28px auto 18px;border:1px solid #ffffff28;border-radius:20px;background:linear-gradient(145deg,#222,#080808);font-size:28px}h1{font-size:clamp(28px,5vw,40px);line-height:1.15;letter-spacing:-.04em;margin:0 0 14px}p{max-width:440px;margin:0 auto;color:#b9b9bf}.line{height:1px;background:#ffffff18;margin:28px 0}.note{font-size:11px;letter-spacing:.16em;color:#888}</style></head><body><main class="card"><div class="brand">VOID DEVELOPMENT</div><div class="mark">◈</div><h1>This script is protected.</h1><p>The source is not displayed in this browser page. Use the generated Roblox loadstring in your supported executor to request the published script.</p><div class="line"></div><div class="note">PROTECTED DELIVERY · VOID DEVELOPMENT</div></main></body></html>`;
        return new Response(page, {
          status: 200,
          headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store, max-age=0", "X-Content-Type-Options": "nosniff", "Referrer-Policy": "no-referrer" }
        });
      }

      const upstream = new URL("https://cqtwmxojwwyeasstuhgb.supabase.co/functions/v1/ario-raw");
      upstream.searchParams.set("s", protectedSlug);
      try {
        const response = await fetch(upstream.toString(), {
          method: "GET",
          headers: { "Accept": "text/plain", "Cache-Control": "no-cache" },
          redirect: "manual"
        });
        const headers = new Headers(response.headers);
        headers.set("Cache-Control", "no-store, max-age=0");
        headers.set("Pragma", "no-cache");
        headers.set("X-Content-Type-Options", "nosniff");
        headers.delete("Location");
        headers.delete("Access-Control-Allow-Origin");
        return new Response(response.body, { status: response.status, statusText: response.statusText, headers });
      } catch {
        return new Response("Protected delivery temporarily unavailable.", {
          status: 502,
          headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" }
        });
      }
    }

    // Site-hosted protected script endpoint for generated Lua loadstrings.
    if (route.startsWith("/script/") && request.method === "GET") {
      let slug = "";
      try { slug = decodeURIComponent(route.slice("/script/".length)); } catch { slug = ""; }
      if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/i.test(slug)) slug = "";
      const key = incoming.searchParams.get("key") || "";
      const protectedPage = () => new Response("<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><meta name='theme-color' content='#050505'><title>Protected · VOID DEVELOPMENT</title><style>*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;background:radial-gradient(ellipse at 50% 0%,rgba(255,255,255,.12) 0,transparent 45%),#050505;color:#fff;font:15px/1.7 system-ui,sans-serif;padding:24px}.card{max-width:620px;text-align:center;padding:48px 36px;border:1px solid rgba(255,255,255,.12);border-radius:28px;background:rgba(15,15,15,.92);box-shadow:0 28px 100px #0008}.mark{font-size:12px;letter-spacing:.35em;color:#fff;font-weight:800}.lock{font-size:42px;margin:24px 0 8px}h1{font-size:clamp(28px,5vw,42px);letter-spacing:-.04em;margin:0 0 12px}p{color:#b4b4b8;margin:0 auto 24px;max-width:430px}.line{height:1px;background:rgba(255,255,255,.12);margin:24px 0}.note{font-size:12px;color:#85858b}</style></head><body><main class='card'><div class='mark'>VOID DEVELOPMENT</div><div class='lock'>⌑</div><h1>This script is protected.</h1><p>This script requires a valid access key. Use the official loader and an authorized key to request access.</p><div class='line'></div><div class='note'>PRIVATE SOURCE · ACCESS CONTROL ENABLED</div></main></body></html>", {status:404,headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
      if (!slug) return protectedPage();
      const wantsHtml = (request.headers.get('accept') || '').includes('text/html');
      const api = new URL("https://cqtwmxojwwyeasstuhgb.supabase.co/functions/v1/script-api");
      api.searchParams.set("action", "load");
      api.searchParams.set("script", slug);
      api.searchParams.set("key", key);
      const upstream = await fetch(api.toString(), { headers: { "Accept": "text/plain" } });
      if (!upstream.ok && wantsHtml) return protectedPage();
      const headers = new Headers(upstream.headers);
      headers.set("Cache-Control", "no-store, max-age=0");
      headers.set("X-Content-Type-Options", "nosniff");
      return new Response(upstream.body, { status: upstream.status, headers });
    }

    // Friendly account URLs open the auth dialog while still serving the static app.
    const url = new URL(request.url);
    if (route === "/admin") {
      // Serve the app shell for the clean /admin URL; the client verifies the signed-in role.
      url.pathname = "/";
      url.searchParams.set("admin", "1");
    } else if (route === "/signup" || route === "/login") {
      url.pathname = "/";
      url.searchParams.set("auth", route === "/signup" ? "signup" : "login");
    } else if (route.startsWith("/scripts/") && route !== "/scripts") {
      const slug = decodeURIComponent(route.slice("/scripts/".length));
      if (!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(slug)) return new Response("Not found", { status: 404, headers: { "Content-Type": "text/plain; charset=utf-8", "X-Content-Type-Options": "nosniff" } });
      url.pathname = "/";
      url.searchParams.set("view", "scripts");
      url.searchParams.set("script", slug);
    } else if (route === "/themes" || route === "/about" || route === "/scripts") {
      url.pathname = "/";
      url.searchParams.set("view", route === "/scripts" ? "scripts" : route.slice(1));
    }

    // Keep the existing key system and add the protected-loader helper.
    const response = await env.ASSETS.fetch(new Request(url, request));
    const type = response.headers.get("content-type") || "";
    if (!type.includes("text/html")) return response;
    const html = await response.text();
    const injected = html.replace(/<\/body>/i, '  <script src="/key-system.js"></script>\n  <script src="/protect-tools.js"></script>\n</body>');
    const headers = new Headers(response.headers);
    headers.delete("content-length");
    return new Response(injected, { status: response.status, statusText: response.statusText, headers });
  }
};
